import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import type { RemoteInspectionAssignment, RemoteInspectionRequirement } from '@pcr/domain';

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const base = import.meta.env.VITE_API_BASE_URL?.trim(); if (!base) throw new Error('VITE_API_BASE_URL is required.');
  const response = await fetch(`${base.replace(/\/$/u, '')}${path}`, init); const payload = await response.json() as { data?: T; error?: { message?: string } }; if (!response.ok || payload.data === undefined) throw new Error(payload.error?.message || `Request failed with ${response.status}.`); return payload.data;
}

async function sha256(file: File): Promise<string> { const digest = await crypto.subtle.digest('SHA-256', await file.arrayBuffer()); return [...new Uint8Array(digest)].map((value) => value.toString(16).padStart(2, '0')).join(''); }
function contentType(file: File): string { const declared = file.type.trim().toLowerCase(); if (declared) return declared; const lower = file.name.toLowerCase(); if (/\.jpe?g$/u.test(lower)) return 'image/jpeg'; if (/\.png$/u.test(lower)) return 'image/png'; if (/\.heic$/u.test(lower)) return 'image/heic'; if (/\.heif$/u.test(lower)) return 'image/heif'; if (/\.mp4$/u.test(lower)) return 'video/mp4'; if (/\.mov$/u.test(lower)) return 'video/quicktime'; if (/\.mp3$/u.test(lower)) return 'audio/mpeg'; if (/\.m4a$/u.test(lower)) return 'audio/mp4'; if (/\.webm$/u.test(lower)) return 'audio/webm'; throw new Error('Unsupported evidence file type.'); }

const RemoteInspectionPage: React.FC = () => {
  const { grantToken = '', assignmentId = '' } = useParams(); const [assignment, setAssignment] = useState<RemoteInspectionAssignment>(); const [commentary, setCommentary] = useState<Record<string,string>>({}); const [evidence, setEvidence] = useState<Record<string,string[]>>({}); const [busy, setBusy] = useState(''); const [error, setError] = useState('');
  const load = async () => { try { setAssignment(await request<RemoteInspectionAssignment>(`/api/v1/external/remote-inspections/${encodeURIComponent(grantToken)}/${encodeURIComponent(assignmentId)}`)); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } };
  useEffect(() => { void load(); }, [assignmentId, grantToken]);

  const upload = async (file: File): Promise<string> => {
    const type = contentType(file); const digest = await sha256(file);
    const session = await request<{ id: string; photoId: string; status: string; resumableUploadUrl?: string; binaryUploadUrl?: string; completionUrl?: string; duplicatePhotoId?: string }>(`/api/v1/external/remote-inspections/${encodeURIComponent(grantToken)}/${encodeURIComponent(assignmentId)}/upload-session`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ fileName: file.name, contentType: type, size: file.size, sha256: digest }) });
    if (session.status === 'duplicate' && session.duplicatePhotoId) return session.duplicatePhotoId;
    const baseUrl = import.meta.env.VITE_API_BASE_URL?.trim() || '';
    const uploadUrl = session.binaryUploadUrl ? `${baseUrl.replace(/\/$/u, '')}${session.binaryUploadUrl}` : session.resumableUploadUrl;
    if (!uploadUrl) throw new Error('Remote inspection evidence upload is not configured.');
    const response = await fetch(uploadUrl, { method: 'PUT', headers: session.binaryUploadUrl ? { 'content-type': type } : { 'content-type': type, 'content-range': `bytes 0-${file.size - 1}/${file.size}` }, body: file }); if (!response.ok) throw new Error(`Evidence upload failed with ${response.status}.`);
    const completionPath = session.completionUrl || `/api/v1/external/remote-inspections/${encodeURIComponent(grantToken)}/${encodeURIComponent(assignmentId)}/upload-session/${encodeURIComponent(session.id)}/complete`;
    const completed = await request<{ photoId: string }>(completionPath, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' }); return completed.photoId;
  };

    const addFiles = async (requirement: RemoteInspectionRequirement, files: FileList | null) => { if (!files?.length) return; setBusy(requirement.id); setError(''); try { const ids = [...(evidence[requirement.id] || [])]; for (const file of Array.from(files)) ids.push(await upload(file)); setEvidence((current) => ({ ...current, [requirement.id]: ids })); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(''); } };
  const submit = async (requirement: RemoteInspectionRequirement) => { setBusy(requirement.id); setError(''); try { await request(`/api/v1/external/remote-inspections/${encodeURIComponent(grantToken)}/${encodeURIComponent(assignmentId)}/submit`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ requirementId: requirement.id, commentary: commentary[requirement.id], evidenceIds: evidence[requirement.id] || [] }) }); await load(); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(''); } };
  if (error && !assignment) return <main className="min-h-screen grid place-items-center bg-gray-50 p-6"><div className="max-w-xl rounded-xl border border-red-200 bg-red-50 p-4 text-red-800">{error}</div></main>;
  if (!assignment) return <main className="min-h-screen grid place-items-center text-sm text-gray-500">Loading inspection...</main>;
  return <main className="min-h-screen bg-gray-50"><header className="border-b bg-white"><div className="mx-auto max-w-3xl p-5"><div className="text-xs font-semibold uppercase tracking-wider text-gray-500">Tenant-assisted inspection</div><h1 className="text-2xl font-bold">Property inspection evidence</h1><p className="mt-1 text-sm text-gray-600">Your evidence is recorded as tenant-supplied and is reviewed before it can be accepted into the professional inspection workflow.</p></div></header><div className="mx-auto max-w-3xl space-y-4 p-5">{error && <div className="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-800">{error}</div>}<div className="rounded-xl border bg-white p-4 text-sm"><strong>Status:</strong> {assignment.status}{assignment.dueAt && <> · Due {new Date(assignment.dueAt).toLocaleString()}</>}</div>{assignment.requirements.map((requirement) => <section key={requirement.id} className="rounded-xl border bg-white p-4"><h2 className="font-semibold">{requirement.label}</h2><p className="mt-1 text-sm text-gray-600">{requirement.instructions}</p><div className="mt-3 text-xs text-gray-500">Required evidence: {requirement.requiredEvidenceCount} · uploaded here: {(evidence[requirement.id] || []).length}</div><input className="mt-3 block text-sm" type="file" accept="image/*,video/mp4,video/quicktime,audio/*" multiple onChange={(e) => void addFiles(requirement, e.target.files)} /><textarea className="mt-3 min-h-24 w-full rounded border px-3 py-2 text-sm" placeholder={requirement.commentaryRequired ? 'Commentary required' : 'Optional commentary'} value={commentary[requirement.id] || ''} onChange={(e) => setCommentary((current) => ({ ...current, [requirement.id]: e.target.value }))} /><button className="mt-3 rounded bg-gray-950 px-4 py-2 text-sm text-white disabled:opacity-50" disabled={busy === requirement.id} onClick={() => void submit(requirement)}>{busy === requirement.id ? 'Working...' : 'Submit item'}</button></section>)}</div></main>;
};
export default RemoteInspectionPage;
